#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Trained traj highlight test (built-in T2 actions and custom trajectories).

Builtin flow (default):
  Idle -> Prepare -> Walking -> WholeBodyDance(kArbicDance) -> Running
       -> Damping stop -> Prepare -> Idle

Custom flow (--custom-traj-json):
  Idle -> Prepare -> Walking -> Load + Activate -> Running (traj_id=UUID)
       -> Damping stop -> Prepare -> Idle -> Unload

Note: ChangeMode(kPrepare) alone does NOT stop when already in PrepareMode.
      Use ChangeMode(kDamping) then ChangeMode(kPrepare).

Usage:
  python test_trained_traj_status.py lo
  python test_trained_traj_status.py lo --builtin-action wave
  python test_trained_traj_status.py lo --custom-traj-json ./arbic_custom_traj.json
"""

from __future__ import annotations

import argparse
import sys
import time
import unittest
from dataclasses import dataclass
from typing import Callable, Optional

import booster_robotics_sdk_python as br

from common import (
    create_loco_client,
    default_network_interface,
    format_status_snapshot,
    init_channel_factory,
    require_highlight_sdk,
    status_name,
    status_to_int,
    usage,
)

ARABIC_BUILTIN_TRAJ_ID = "0"
T2_WAVE_HAND_TRAJ_ID = "2005"


@dataclass(frozen=True)
class StatusSnapshot:
    status: int
    traj_id: str

    @classmethod
    def from_rpc(cls, resp: br.GetTrainedTrajStatusResponse) -> "StatusSnapshot":
        return cls(status_to_int(resp.status), resp.traj_id)

    def __str__(self) -> str:
        return format_status_snapshot(self.status, self.traj_id)


def wait_for_rpc(
    rpc_getter: Callable[[], StatusSnapshot],
    *,
    expected: int,
    timeout_s: float,
    traj_id: Optional[str] = None,
    label: str = "",
) -> StatusSnapshot:
    deadline = time.time() + timeout_s
    last = None
    while time.time() < deadline:
        last = rpc_getter()
        if last.status != expected:
            time.sleep(0.2)
            continue
        if traj_id is not None and last.traj_id != traj_id:
            time.sleep(0.2)
            continue
        print(f"[OK] {label}: {last}")
        return last

    raise TimeoutError(
        f"{label} timed out after {timeout_s}s, want {status_name(expected)}; "
        f"last={last}"
    )


def build_arg_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(add_help=False)
    p.add_argument("network_interface", nargs="?", default=None)
    p.add_argument("robot_name", nargs="?", default=None)
    p.add_argument(
        "--builtin-action",
        choices=("arabic", "wave"),
        default="arabic",
    )
    p.add_argument("--custom-traj-json", default=None)
    p.add_argument("--running-timeout", type=float, default=15.0)
    p.add_argument("--idle-timeout", type=float, default=30.0)
    p.add_argument("--dance-seconds", type=float, default=5.0)
    return p


TEST_FLAGS, UNITTEST_ARGV = build_arg_parser().parse_known_args(sys.argv[1:])
sys.argv = [sys.argv[0]] + UNITTEST_ARGV


class HighlightTestBase(unittest.TestCase):
    client: br.B1LocoClient = None  # type: ignore

    @classmethod
    def setUpClass(cls) -> None:
        require_highlight_sdk()
        net_if = TEST_FLAGS.network_interface or default_network_interface()
        init_channel_factory(net_if)
        cls.client = create_loco_client(TEST_FLAGS.robot_name)
        time.sleep(0.5)

    def rpc(self) -> StatusSnapshot:
        return StatusSnapshot.from_rpc(self.client.GetTrainedTrajStatus())

    def _stop_dance_and_stand(self) -> None:
        print("ChangeMode(kDamping) to stop dance")
        self.client.ChangeMode(br.RobotMode.kDamping)
        time.sleep(2.0)
        print("ChangeMode(kPrepare) back to stand")
        self.client.ChangeMode(br.RobotMode.kPrepare)
        time.sleep(1.0)

    def _ensure_idle_before(self, label: str) -> None:
        snap = self.rpc()
        print(f"[1] {label} before dance: {snap}")
        if snap.status == int(br.TrainedTrajStatus.kRunning):
            print("Already Running, stop with Damping first")
            self._stop_dance_and_stand()
            wait_for_rpc(
                self.rpc,
                expected=int(br.TrainedTrajStatus.kIdle),
                timeout_s=TEST_FLAGS.idle_timeout,
                label=f"{label} force Idle before test",
            )
        else:
            self.assertEqual(snap.status, int(br.TrainedTrajStatus.kIdle))

    def _enter_walking(self) -> None:
        # DampingMode -> WalkingMode requires an explicit recovery target in
        # Motion. Normalize through PrepareMode first, then enter walking mode.
        print("ChangeMode(kPrepare) before walking")
        self.client.ChangeMode(br.RobotMode.kPrepare)
        time.sleep(1.0)
        print("ChangeMode(kWalking)")
        self.client.ChangeMode(br.RobotMode.kWalking)
        time.sleep(1.0)

    def _dance_then_stop(self, label: str) -> None:
        print(f"Dancing {TEST_FLAGS.dance_seconds}s, then stop (Damping -> Prepare)")
        time.sleep(TEST_FLAGS.dance_seconds)
        self._stop_dance_and_stand()
        wait_for_rpc(
            self.rpc,
            expected=int(br.TrainedTrajStatus.kIdle),
            timeout_s=TEST_FLAGS.idle_timeout,
            label=f"{label} Idle after stop",
        )


class TestBuiltinArabicHighlight(HighlightTestBase):
    @unittest.skipIf(
        TEST_FLAGS.custom_traj_json or TEST_FLAGS.builtin_action != "arabic",
        "Arabic builtin test not selected",
    )
    def test_arbic_builtin_idle_running_stop_idle(self) -> None:
        self._ensure_idle_before("builtin")
        self._enter_walking()

        print("WholeBodyDance(kArbicDance)")
        self.client.WholeBodyDance(br.WholeBodyDanceId.kArbicDance)

        wait_for_rpc(
            self.rpc,
            expected=int(br.TrainedTrajStatus.kRunning),
            timeout_s=TEST_FLAGS.running_timeout,
            traj_id=ARABIC_BUILTIN_TRAJ_ID,
            label="builtin Arabic Running",
        )

        self._dance_then_stop("builtin")
        print("[DONE] Builtin Arabic highlight test passed.")


class TestT2WaveHandHighlight(HighlightTestBase):
    @unittest.skipIf(
        TEST_FLAGS.custom_traj_json or TEST_FLAGS.builtin_action != "wave",
        "T2 wave hand test not selected",
    )
    def test_t2_wave_hand_uses_public_action_id(self) -> None:
        self._ensure_idle_before("T2 wave hand")
        self._enter_prepare()

        print("WaveHand(kHandOpen)")
        self.client.WaveHand(br.HandAction.kHandOpen)

        wait_for_rpc(
            self.rpc,
            expected=int(br.TrainedTrajStatus.kRunning),
            timeout_s=TEST_FLAGS.running_timeout,
            traj_id=T2_WAVE_HAND_TRAJ_ID,
            label="T2 wave hand Running",
        )

        self._dance_then_stop("T2 wave hand")
        print("[DONE] T2 wave hand highlight test passed.")


class TestCustomArabicHighlight(HighlightTestBase):
    @unittest.skipIf(
        not TEST_FLAGS.custom_traj_json,
        "custom traj test skipped (no --custom-traj-json)",
    )
    def test_custom_arbic_idle_running_stop_idle(self) -> None:
        with open(TEST_FLAGS.custom_traj_json, "r", encoding="utf-8") as f:
            traj_obj = br.CustomTrainedTraj.from_json_str(f.read())

        self._ensure_idle_before("custom")
        self._enter_walking()

        print(f"LoadCustomTrainedTraj({TEST_FLAGS.custom_traj_json})")
        tid = self.client.LoadCustomTrainedTraj(traj_obj)
        print(f"Loaded tid={tid}")
        self.assertTrue(tid)

        print(f"ActivateCustomTrainedTraj({tid})")
        self.client.ActivateCustomTrainedTraj(tid)

        wait_for_rpc(
            self.rpc,
            expected=int(br.TrainedTrajStatus.kRunning),
            timeout_s=TEST_FLAGS.running_timeout,
            traj_id=tid,
            label="custom Arabic Running",
        )

        self._dance_then_stop("custom")

        try:
            print(f"UnloadCustomTrainedTraj({tid})")
            self.client.UnloadCustomTrainedTraj(tid)
        except Exception as exc:
            print(f"UnloadCustomTrainedTraj warning: {exc}")

        print("[DONE] Custom Arabic highlight test passed.")


def main() -> int:
    if len(sys.argv) > 1 and sys.argv[1] in ("-h", "--help"):
        usage(__file__)
        print("\nOptions:")
        print("  --builtin-action ACTION  arabic or wave (default: arabic)")
        print("  --custom-traj-json PATH  run custom test only (default: builtin Arabic)")
        print("  --running-timeout SEC    wait for Running (default 15)")
        print("  --idle-timeout SEC       wait for Idle after stop (default 30)")
        print("  --dance-seconds SEC      dance before stop (default 5)")
        return 0

    loader = unittest.TestLoader()
    if TEST_FLAGS.custom_traj_json:
        suite = loader.loadTestsFromTestCase(TestCustomArabicHighlight)
    elif TEST_FLAGS.builtin_action == "wave":
        suite = loader.loadTestsFromTestCase(TestT2WaveHandHighlight)
    else:
        suite = loader.loadTestsFromTestCase(TestBuiltinArabicHighlight)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    sys.exit(main())
